class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def reverseEvenGroups(nums):
    dummy = ListNode(0, build(nums))
    prev = dummy
    size = 1
    while prev.next:
        cnt = 0
        node = prev.next
        while node and cnt < size:
            node = node.next
            cnt += 1
        if cnt % 2 == 0:
            tail = prev.next
            for _ in range(cnt - 1):
                nxt = tail.next
                tail.next = nxt.next
                nxt.next = prev.next
                prev.next = nxt
            prev = tail
        else:
            for _ in range(cnt):
                prev = prev.next
        size += 1
    return dump(dummy.next)
